INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001420020','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001420020","revision":1,"targetId":"80000000-0000-4000-8000-000000014202","prompt":"Auf die unerwartete Nachricht war ihre erste ___ ein erstauntes Schweigen.","instruction":{"en":"Choose the word that correctly completes the sentence.","de":"Wähle das Wort, das den Satz richtig ergänzt."},"hint":{"en":"Her silence followed the news.","de":"Ihr Schweigen folgte auf die Nachricht."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Reaktion"},{"id":"1","text":"Bewerbung"},{"id":"2","text":"Lieferung"},{"id":"3","text":"Verhandlung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"0"}]}],"explanation":{"en":"Reaktion is a response to something.","de":"Reaktion ist eine Antwort auf ein Ereignis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf die unerwartete Nachricht war ihre erste Reaktion ein erstauntes Schweigen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1921 (ade0c9fedb4280ad51beb12005f464a41ebe05b9db4430a2455da2ac8fcc390f), 2026-10-29; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
