INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001420021','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001420021","revision":1,"targetId":"80000000-0000-4000-8000-000000014202","prompt":"Ein Kind lacht, als es eine lustige Geschichte hört. Was ist das Lachen?","instruction":{"en":"Read the situation and choose the one correct answer.","de":"Lies die Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The laughter happens because of the story.","de":"Das Lachen entsteht als Antwort auf die Geschichte."},"options":[{"id":"0","text":"Ursache"},{"id":"1","text":"Vorhersage"},{"id":"2","text":"Reaktion"},{"id":"3","text":"Anweisung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"The laughter is a Reaktion.","de":"Das Lachen ist eine Reaktion."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Lachen ist eine Reaktion auf die Geschichte.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1921 (ade0c9fedb4280ad51beb12005f464a41ebe05b9db4430a2455da2ac8fcc390f), 2026-10-29; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
