INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001420030','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001420030","revision":1,"targetId":"80000000-0000-4000-8000-000000014203","prompt":"Der Plan klang einfach, aber in der ___ gab es viele unerwartete Probleme.","instruction":{"en":"Choose the word that correctly completes the sentence.","de":"Wähle das Wort, das den Satz richtig ergänzt."},"hint":{"en":"What actually happened differed from the plan.","de":"Was tatsächlich geschah, unterschied sich vom Plan."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Fantasie"},{"id":"1","text":"Werbung"},{"id":"2","text":"Erfindung"},{"id":"3","text":"Realität"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Realität is the actual state of affairs.","de":"Realität ist die tatsächliche Wirklichkeit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Plan klang einfach, aber in der Realität gab es viele unerwartete Probleme.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1922 (83949f8a411de8e12ee404c9819c12e1db303b1002696cb09fa3a8b80231d34c), 2026-10-29; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
