INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001420031','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001420031","revision":1,"targetId":"80000000-0000-4000-8000-000000014203","prompt":"Eine Firma verspricht Lieferung am nächsten Tag; tatsächlich dauert es fünf Tage. Was beschreibt die tatsächliche Lage?","instruction":{"en":"Read the situation and choose the one correct answer.","de":"Lies die Situation und wähle die einzige richtige Antwort."},"hint":{"en":"Look at what really occurs.","de":"Achte darauf, was wirklich geschieht."},"options":[{"id":"0","text":"Wunsch"},{"id":"1","text":"Realität"},{"id":"2","text":"Prognose"},{"id":"3","text":"Gerücht"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"The actual delay is the Realität.","de":"Die tatsächliche Verzögerung ist die Realität."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Realität ist eine Lieferzeit von fünf Tagen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1922 (83949f8a411de8e12ee404c9819c12e1db303b1002696cb09fa3a8b80231d34c), 2026-10-29; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
